const updateDiscount = `-- name: UpdateDiscount :one
UPDATE discounts SET
name=$1,description=$2,type=$3,value=$4,currency=$5,
starts_at=$6,ends_at=$7,max_uses=$8,min_order=$9,max_discount=$10,
notify_enabled=$11,notify_days=$12,notify_audience=$13,notify_text=$14,
enabled=$15 WHERE id=$16 AND deleted=0 RETURNING id, name, description, type, value, currency, starts_at, ends_at, max_uses, used_count, min_order, max_discount, notify_enabled, notify_days, notify_audience, notify_text, enabled, deleted, created_at, created_by
`

type UpdateDiscountParams struct {
	Name           string
	Description    string
	Type           string
	Value          int64
	Currency       string
	StartsAt       int64
	EndsAt         int64
	MaxUses        sql.NullInt64
	MinOrder       int64
	MaxDiscount    int64
	NotifyEnabled  int64
	NotifyDays     string
	NotifyAudience string
	NotifyText     string
	Enabled        int64
	ID             int64
}

func (q *Queries) UpdateDiscount(ctx context.Context, arg UpdateDiscountParams) (Discount, error) {
	row := q.db.QueryRowContext(ctx, updateDiscount,
		arg.Name,
		arg.Description,
		arg.Type,
		arg.Value,
		arg.Currency,
		arg.StartsAt,
		arg.EndsAt,
		arg.MaxUses,
		arg.MinOrder,
		arg.MaxDiscount,
		arg.NotifyEnabled,
		arg.NotifyDays,
		arg.NotifyAudience,
		arg.NotifyText,
		arg.Enabled,
		arg.ID,
	)
	var i Discount
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Description,
		&i.Type,
		&i.Value,
		&i.Currency,
		&i.StartsAt,
		&i.EndsAt,
		&i.MaxUses,
		&i.UsedCount,
		&i.MinOrder,
		&i.MaxDiscount,
		&i.NotifyEnabled,
		&i.NotifyDays,
		&i.NotifyAudience,
		&i.NotifyText,
		&i.Enabled,
		&i.Deleted,
		&i.CreatedAt,
		&i.CreatedBy,
	)
	return i, err
}
